cy.ValidarIngresoAdmin();
// Navega a Esquemas de Valuación y espera la tabla (ver L022). La descripción con la marca
// CYPRESS es la que usa el cleaner para reconocer qué esquemas borrar.
cy.guardarEsquemasValuacion();
cy.altaEsquemaValuacion(
  'ARS - USD MEP',
  'Valuación en pesos con cotizaciones en USD al t/c MEP CYPRESS.',
  'Valuacion BYMA ARS + Instrumentos No Liquidos - USD MEP',
  'Esquema ARS - USD MEP'
);
cy.validarEsquemaValuacionCreado('ARS - USD MEP');
// Se crean AMBOS esquemas (MEP y CCL) siempre, para poder switchear el activo
// (Constants.VALUATION_SCHEME) editando VALUATION_SCHEME en el target JSON sin depender
// de crear el esquema en el momento. El cleaner los borra a ambos por la marca CYPRESS de la descripción.
cy.altaEsquemaValuacion(
  'ARS - USD CCL',
  'Valuación en pesos con cotizaciones en USD al t/c CCL CYPRESS.',
  'Valuacion BYMA ARS + Instrumentos No Liquidos - USD CCL',
  'Esquema ARS - USD CCL'
);
cy.validarEsquemaValuacionCreado('ARS - USD CCL');

// Navega a Definiciones de Gastos y espera la tabla. El cleaner no borra gastos: se crean solo si faltan.
cy.guardarGastos();
cy.altaGasto('Comisión', 'Comisión del Broker');
cy.altaGasto('Comisión', 'Comisión del Mercado');
cy.altaGasto('Impuesto', 'IVA');
cy.validarGastoCreado('Comisión del Broker');
cy.validarGastoCreado('Comisión del Mercado');
cy.validarGastoCreado('IVA');
